"""Priority scoring for tasks."""


def calculate_priority(task):
    """Higher score = more urgent. Combines stated urgency with how soon
    the task is due; overdue tasks always outrank non-overdue ones."""
    if task.due_in_days < 0:
        return 100 + task.urgency
    return task.urgency * 10 // (task.due_in_days + 1)

